-- agency_vehicle_create (from 20261008000000_agency_fleet_foundation.sql; authority -> fleet_manager)
CREATE OR REPLACE FUNCTION public.agency_vehicle_create(
  p_rc_number text,
  p_vehicle_type text,
  p_insurance_expiry date DEFAULT NULL,
  p_fitness_expiry date DEFAULT NULL,
  p_permit_expiry date DEFAULT NULL,
  p_puc_expiry date DEFAULT NULL,
  p_payload_kg numeric DEFAULT NULL,
  p_body_length_m numeric DEFAULT NULL,
  p_body_width_m numeric DEFAULT NULL,
  p_body_height_m numeric DEFAULT NULL,
  p_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_catalog public.trucks%ROWTYPE;
  v_inserted public.agency_trucks%ROWTYPE;
  v_existing public.agency_trucks%ROWTYPE;
BEGIN
  IF p_rc_number IS NULL OR btrim(p_rc_number) = '' THEN
    RAISE EXCEPTION 'RC number is required.';
  END IF;

  IF p_vehicle_type IS NULL OR btrim(p_vehicle_type) = '' THEN
    RAISE EXCEPTION 'Vehicle type is required.';
  END IF;

  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['fleet_manager']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT * INTO v_catalog FROM public.trucks WHERE code = p_vehicle_type;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unknown vehicle type.';
  END IF;

  -- ONE atomic write; a replayed (agency_id, rc_number) conflicts on the
  -- settlement key and writes nothing.
  INSERT INTO public.agency_trucks (
    agency_id, vehicle_type, rc_number,
    insurance_expiry, fitness_expiry, permit_expiry, puc_expiry,
    payload_kg, body_length_m, body_width_m, body_height_m, notes
  ) VALUES (
    v_agency_id, p_vehicle_type, btrim(p_rc_number),
    p_insurance_expiry, p_fitness_expiry, p_permit_expiry, p_puc_expiry,
    p_payload_kg,
    COALESCE(p_body_length_m, v_catalog.length),
    COALESCE(p_body_width_m, v_catalog.width),
    COALESCE(p_body_height_m, v_catalog.height),
    p_notes
  )
  ON CONFLICT (agency_id, rc_number) DO NOTHING
  RETURNING * INTO v_inserted;

  IF v_inserted.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state', 'created',
      'vehicle', to_jsonb(v_inserted),
      'version', v_inserted.version
    );
  END IF;

  -- Idempotent replay: return the existing row unchanged.
  SELECT * INTO v_existing
  FROM public.agency_trucks
  WHERE agency_id = v_agency_id AND rc_number = btrim(p_rc_number);

  RETURN jsonb_build_object(
    'ok', true,
    'state', 'idempotent_replay',
    'vehicle', to_jsonb(v_existing),
    'version', v_existing.version
  );
END;
$$;

-- agency_vehicle_update (from 20261008000000_agency_fleet_foundation.sql; authority -> fleet_manager)
CREATE OR REPLACE FUNCTION public.agency_vehicle_update(
  p_vehicle_id uuid,
  p_expected_version integer,
  p_patch jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_owned boolean;
  v_updated public.agency_trucks%ROWTYPE;
  v_current_version integer;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['fleet_manager']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.agency_trucks
    WHERE id = p_vehicle_id AND agency_id = v_agency_id
  ) INTO v_owned;
  IF NOT v_owned THEN
    RAISE EXCEPTION 'Vehicle not found or access denied.';
  END IF;

  -- The version trigger bumps exactly once; the WHERE clause is the atomic
  -- expected-version check. A zero-row update IS the conflict (no write).
  UPDATE public.agency_trucks t SET
    is_available = CASE WHEN p_patch ? 'is_available' THEN COALESCE((p_patch->>'is_available')::boolean, t.is_available) ELSE t.is_available END,
    notes = CASE WHEN p_patch ? 'notes' THEN p_patch->>'notes' ELSE t.notes END,
    insurance_expiry = CASE WHEN p_patch ? 'insurance_expiry' THEN (p_patch->>'insurance_expiry')::date ELSE t.insurance_expiry END,
    fitness_expiry = CASE WHEN p_patch ? 'fitness_expiry' THEN (p_patch->>'fitness_expiry')::date ELSE t.fitness_expiry END,
    permit_expiry = CASE WHEN p_patch ? 'permit_expiry' THEN (p_patch->>'permit_expiry')::date ELSE t.permit_expiry END,
    puc_expiry = CASE WHEN p_patch ? 'puc_expiry' THEN (p_patch->>'puc_expiry')::date ELSE t.puc_expiry END,
    payload_kg = CASE WHEN p_patch ? 'payload_kg' THEN (p_patch->>'payload_kg')::numeric ELSE t.payload_kg END,
    body_length_m = CASE WHEN p_patch ? 'body_length_m' THEN (p_patch->>'body_length_m')::numeric ELSE t.body_length_m END,
    body_width_m = CASE WHEN p_patch ? 'body_width_m' THEN (p_patch->>'body_width_m')::numeric ELSE t.body_width_m END,
    body_height_m = CASE WHEN p_patch ? 'body_height_m' THEN (p_patch->>'body_height_m')::numeric ELSE t.body_height_m END,
    maintenance_blocked = CASE WHEN p_patch ? 'maintenance_blocked' THEN COALESCE((p_patch->>'maintenance_blocked')::boolean, t.maintenance_blocked) ELSE t.maintenance_blocked END,
    maintenance_block_reason = CASE WHEN p_patch ? 'maintenance_block_reason' THEN p_patch->>'maintenance_block_reason' ELSE t.maintenance_block_reason END,
    maintenance_blocked_until = CASE WHEN p_patch ? 'maintenance_blocked_until' THEN (p_patch->>'maintenance_blocked_until')::timestamptz ELSE t.maintenance_blocked_until END
  WHERE t.id = p_vehicle_id
    AND t.agency_id = v_agency_id
    AND t.version = p_expected_version
  RETURNING * INTO v_updated;

  IF v_updated.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state', 'updated',
      'vehicle', to_jsonb(v_updated),
      'version', v_updated.version
    );
  END IF;

  SELECT version INTO v_current_version
  FROM public.agency_trucks
  WHERE id = p_vehicle_id;

  RETURN jsonb_build_object(
    'ok', false,
    'error', 'version_conflict',
    'current_version', v_current_version
  );
END;
$$;

-- agency_driver_employment_create (from 20261008000000_agency_fleet_foundation.sql; authority -> fleet_manager)
CREATE OR REPLACE FUNCTION public.agency_driver_employment_create(
  p_driver_id uuid,
  p_licence_number text DEFAULT NULL,
  p_licence_class text DEFAULT NULL,
  p_licence_expiry date DEFAULT NULL,
  p_contact_phone text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_inserted public.agency_driver_employment%ROWTYPE;
  v_existing public.agency_driver_employment%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['fleet_manager']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  IF NOT public.driver_is_approved_for_assignment(p_driver_id) THEN
    RAISE EXCEPTION 'Driver is not approved for assignment.';
  END IF;

  INSERT INTO public.agency_driver_employment (
    agency_id, driver_id, licence_number, licence_class, licence_expiry, contact_phone
  ) VALUES (
    v_agency_id, p_driver_id, p_licence_number, p_licence_class, p_licence_expiry, p_contact_phone
  )
  ON CONFLICT (driver_id) WHERE status = 'active' DO NOTHING
  RETURNING * INTO v_inserted;

  IF v_inserted.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state', 'created',
      'employment', to_jsonb(v_inserted),
      'version', v_inserted.version
    );
  END IF;

  -- Active employment already exists: replay for the SAME agency, denial for
  -- a foreign one (mirrors the one-truck cross-agency posture).
  SELECT * INTO v_existing
  FROM public.agency_driver_employment
  WHERE driver_id = p_driver_id AND status = 'active';

  IF v_existing.agency_id = v_agency_id THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state', 'idempotent_replay',
      'employment', to_jsonb(v_existing),
      'version', v_existing.version
    );
  END IF;

  RAISE EXCEPTION 'Driver already has an active employment record.';
END;
$$;

-- agency_driver_employment_update (from 20261008000000_agency_fleet_foundation.sql; authority -> fleet_manager)
CREATE OR REPLACE FUNCTION public.agency_driver_employment_update(
  p_employment_id uuid,
  p_expected_version integer,
  p_patch jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_owned boolean;
  v_updated public.agency_driver_employment%ROWTYPE;
  v_current_version integer;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['fleet_manager']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.agency_driver_employment
    WHERE id = p_employment_id AND agency_id = v_agency_id
  ) INTO v_owned;
  IF NOT v_owned THEN
    RAISE EXCEPTION 'Employment record not found or access denied.';
  END IF;

  UPDATE public.agency_driver_employment e SET
    licence_number = CASE WHEN p_patch ? 'licence_number' THEN p_patch->>'licence_number' ELSE e.licence_number END,
    licence_class = CASE WHEN p_patch ? 'licence_class' THEN p_patch->>'licence_class' ELSE e.licence_class END,
    licence_expiry = CASE WHEN p_patch ? 'licence_expiry' THEN (p_patch->>'licence_expiry')::date ELSE e.licence_expiry END,
    contact_phone = CASE WHEN p_patch ? 'contact_phone' THEN p_patch->>'contact_phone' ELSE e.contact_phone END
  WHERE e.id = p_employment_id
    AND e.agency_id = v_agency_id
    AND e.version = p_expected_version
  RETURNING * INTO v_updated;

  IF v_updated.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state', 'updated',
      'employment', to_jsonb(v_updated),
      'version', v_updated.version
    );
  END IF;

  SELECT version INTO v_current_version
  FROM public.agency_driver_employment
  WHERE id = p_employment_id;

  RETURN jsonb_build_object(
    'ok', false,
    'error', 'version_conflict',
    'current_version', v_current_version
  );
END;
$$;

-- agency_driver_employment_end (from 20261008000000_agency_fleet_foundation.sql; authority -> fleet_manager)
CREATE OR REPLACE FUNCTION public.agency_driver_employment_end(
  p_employment_id uuid,
  p_expected_version integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_owned boolean;
  v_current public.agency_driver_employment%ROWTYPE;
  v_updated public.agency_driver_employment%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['fleet_manager']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.agency_driver_employment
    WHERE id = p_employment_id AND agency_id = v_agency_id
  ) INTO v_owned;
  IF NOT v_owned THEN
    RAISE EXCEPTION 'Employment record not found or access denied.';
  END IF;

  -- Exactly-once end: an already-ended row with the matching expected version
  -- replays as already_ended WITHOUT a second write (version stays put).
  SELECT * INTO v_current
  FROM public.agency_driver_employment
  WHERE id = p_employment_id;

  IF v_current.status = 'ended' THEN
    IF v_current.version = p_expected_version THEN
      RETURN jsonb_build_object(
        'ok', true,
        'state', 'already_ended',
        'employment', to_jsonb(v_current),
        'version', v_current.version
      );
    END IF;
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'version_conflict',
      'current_version', v_current.version
    );
  END IF;

  UPDATE public.agency_driver_employment e SET
    status = 'ended'
  WHERE e.id = p_employment_id
    AND e.agency_id = v_agency_id
    AND e.version = p_expected_version
  RETURNING * INTO v_updated;

  IF v_updated.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state', 'ended',
      'employment', to_jsonb(v_updated),
      'version', v_updated.version
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', false,
    'error', 'version_conflict',
    'current_version', v_current.version
  );
END;
$$;

-- agency_driver_invitation_create (from 20261011000000_agency_members_clients_tariffs.sql; authority -> fleet_manager)
CREATE OR REPLACE FUNCTION public.agency_driver_invitation_create(
  p_invited_phone text,
  p_expires_in_days integer DEFAULT 7,
  p_idempotency_key text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_phone text := regexp_replace(btrim(coalesce(p_invited_phone, '')), '[[:space:]]', '', 'g');
  v_token text;
  v_existing public.agency_driver_invitations%ROWTYPE;
  v_inserted public.agency_driver_invitations%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['fleet_manager']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  IF v_key = '' THEN
    RAISE EXCEPTION 'Idempotency key is required.';
  END IF;

  IF v_phone !~ '^\+?[0-9]{10,15}$' THEN
    RAISE EXCEPTION 'Driver phone is invalid.';
  END IF;

  IF p_expires_in_days IS NULL OR p_expires_in_days < 1 OR p_expires_in_days > 30 THEN
    RAISE EXCEPTION 'Invitation expiry must be between 1 and 30 days.';
  END IF;

  SELECT * INTO v_existing
  FROM public.agency_driver_invitations
  WHERE agency_id = v_agency_id AND idempotency_key = v_key;

  IF FOUND THEN
    IF v_existing.invited_phone = v_phone THEN
      RETURN jsonb_build_object('ok', true, 'state', 'idempotent_replay', 'invitation', to_jsonb(v_existing) - 'token_hash');
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_reused');
  END IF;

  UPDATE public.agency_driver_invitations
  SET status = 'expired', version = version + 1
  WHERE agency_id = v_agency_id
    AND invited_phone = v_phone
    AND status = 'pending'
    AND expires_at <= now();

  IF EXISTS (
    SELECT 1 FROM public.agency_driver_invitations
    WHERE agency_id = v_agency_id AND invited_phone = v_phone AND status = 'pending'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invitation_already_pending');
  END IF;

  v_token := public.agency_random_token();

  INSERT INTO public.agency_driver_invitations (
    agency_id, invited_phone, token_hash, status, expires_at, idempotency_key, created_by
  ) VALUES (
    v_agency_id, v_phone, public.agency_token_hash(v_token), 'pending',
    now() + make_interval(days => p_expires_in_days), v_key, auth.uid()
  )
  RETURNING * INTO v_inserted;

  RETURN jsonb_build_object(
    'ok', true,
    'state', 'created',
    'token', v_token,
    'invitation', to_jsonb(v_inserted) - 'token_hash'
  );
END;
$$;

-- agency_driver_invitation_revoke (from 20261011000000_agency_members_clients_tariffs.sql; authority -> fleet_manager)
CREATE OR REPLACE FUNCTION public.agency_driver_invitation_revoke(
  p_invitation_id uuid,
  p_expected_version integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_current public.agency_driver_invitations%ROWTYPE;
  v_updated public.agency_driver_invitations%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['fleet_manager']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT * INTO v_current
  FROM public.agency_driver_invitations
  WHERE id = p_invitation_id AND agency_id = v_agency_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Driver invitation not found or access denied.';
  END IF;

  IF v_current.status = 'revoked' THEN
    IF v_current.version = p_expected_version THEN
      RETURN jsonb_build_object('ok', true, 'state', 'already_revoked', 'invitation', to_jsonb(v_current) - 'token_hash');
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'version_conflict', 'current_version', v_current.version);
  END IF;

  IF v_current.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invitation_not_pending');
  END IF;

  IF v_current.version <> p_expected_version THEN
    RETURN jsonb_build_object('ok', false, 'error', 'version_conflict', 'current_version', v_current.version);
  END IF;

  UPDATE public.agency_driver_invitations
  SET status = 'revoked', revoked_at = now(), version = version + 1
  WHERE id = p_invitation_id
  RETURNING * INTO v_updated;

  RETURN jsonb_build_object('ok', true, 'state', 'revoked', 'invitation', to_jsonb(v_updated) - 'token_hash');
END;
$$;

-- reserve_fleet_assignment (from 20261010000000_fleet_assignment_reservations.sql; authority -> dispatcher)
CREATE OR REPLACE FUNCTION public.reserve_fleet_assignment(
  p_agency_job_id uuid,
  p_job_offer_id uuid,
  p_vehicle_id uuid,
  p_driver_employment_id uuid,
  p_window_start timestamptz,
  p_window_end timestamptz,
  p_expected_vehicle_version integer,
  p_idempotency_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_now timestamptz := NOW();
  v_job public.agency_jobs%ROWTYPE;
  v_employment public.agency_driver_employment%ROWTYPE;
  v_vehicle public.agency_trucks%ROWTYPE;
  v_offer public.job_offers%ROWTYPE;
  v_existing public.fleet_assignment_reservations%ROWTYPE;
  v_inserted public.fleet_assignment_reservations%ROWTYPE;
  v_message text;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['dispatcher']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  IF p_window_start IS NULL OR p_window_end IS NULL THEN
    RAISE EXCEPTION 'Reservation window is required.';
  END IF;

  IF p_window_end <= p_window_start THEN
    RAISE EXCEPTION 'Reservation window must end after it starts.';
  END IF;

  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'Idempotency key is required.';
  END IF;

  -- (a) Idempotent replay, scoped to the caller agency. Same key + same request
  --     returns the stored reservation; same key + different request is refused.
  SELECT * INTO v_existing
  FROM public.fleet_assignment_reservations
  WHERE agency_id = v_agency_id
    AND idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.agency_job_id = p_agency_job_id
       AND v_existing.job_offer_id = p_job_offer_id
       AND v_existing.vehicle_id = p_vehicle_id
       AND v_existing.driver_employment_id = p_driver_employment_id
       AND v_existing.window_start = p_window_start
       AND v_existing.window_end = p_window_end THEN
      RETURN jsonb_build_object(
        'ok', true,
        'state', 'idempotent_replay',
        'reservation', to_jsonb(v_existing),
        'version', v_existing.version
      );
    END IF;

    RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_reused');
  END IF;

  -- (b) Settle this agency's stale offers first, so an expired hold never blocks.
  PERFORM public.release_stale_fleet_reservations(v_agency_id, v_now);

  -- (c) Caller-owned job, employment and vehicle. Foreign ids fail closed as
  --     not found, never as a different denial.
  SELECT * INTO v_job
  FROM public.agency_jobs
  WHERE id = p_agency_job_id
    AND agency_id = v_agency_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Agency job not found or access denied.';
  END IF;

  SELECT * INTO v_employment
  FROM public.agency_driver_employment
  WHERE id = p_driver_employment_id
    AND agency_id = v_agency_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Employment record not found or access denied.';
  END IF;

  SELECT * INTO v_vehicle
  FROM public.agency_trucks
  WHERE id = p_vehicle_id
    AND agency_id = v_agency_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vehicle not found or access denied.';
  END IF;

  IF v_job.status NOT IN ('pending', 'accepted') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'agency_job_not_open');
  END IF;

  -- (d) Expected vehicle version: the caller acted on a stale vehicle state.
  IF v_vehicle.version <> p_expected_vehicle_version THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'version_conflict',
      'current_version', v_vehicle.version
    );
  END IF;

  -- (e) TO-144-D1 eligibility, evaluated at BOTH window edges. The vehicle
  --     predicate covers availability, maintenance flag and blocked-until,
  --     and document expiry; the driver predicate covers active employment for
  --     this agency, approval and licence validity.
  IF NOT (
    public.agency_vehicle_allocation_eligible(p_vehicle_id, p_window_start)
    AND public.agency_vehicle_allocation_eligible(p_vehicle_id, p_window_end)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'vehicle_not_eligible');
  END IF;

  IF NOT (
    public.agency_driver_allocation_eligible(v_employment.driver_id, v_agency_id, p_window_start)
    AND public.agency_driver_allocation_eligible(v_employment.driver_id, v_agency_id, p_window_end)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'driver_not_eligible');
  END IF;

  -- (f) The offer must be live for this job's shipment and this driver:
  --     pending and unexpired, or already accepted.
  SELECT * INTO v_offer
  FROM public.job_offers
  WHERE id = p_job_offer_id;

  IF NOT FOUND
     OR v_offer.shipment_id IS DISTINCT FROM v_job.shipment_id
     OR v_offer.driver_id IS DISTINCT FROM v_employment.driver_id
     OR NOT (
       v_offer.status = 'accepted'
       OR (v_offer.status = 'pending' AND v_offer.expires_at > v_now)
     ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'offer_not_active');
  END IF;

  -- (g) One active assignment per agency job (the partial unique index is the
  --     backstop for a concurrent insert, handled below).
  IF EXISTS (
    SELECT 1
    FROM public.fleet_assignment_reservations r
    WHERE r.agency_job_id = p_agency_job_id
      AND r.status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'agency_job_already_assigned');
  END IF;

  -- (h) Write. The reservation is the authority for vehicle/driver allocation.
  --     agency_jobs.truck_id / driver_id are NOT written here: the TO-142 guard
  --     trg_agency_jobs_driver_assignment only admits a driver already on the
  --     legacy agency_trucks.driver_id model, which is a separate relationship
  --     from agency_driver_employment (see the header, section 7). The overlap
  --     guard raises inside the INSERT; the EXCEPTION block turns that into a
  --     typed result with nothing written.
  BEGIN
    INSERT INTO public.fleet_assignment_reservations (
      agency_id, agency_job_id, job_offer_id, vehicle_id, driver_employment_id, driver_id,
      window_start, window_end, status, idempotency_key
    ) VALUES (
      v_agency_id, p_agency_job_id, p_job_offer_id, p_vehicle_id, v_employment.id, v_employment.driver_id,
      p_window_start, p_window_end, 'active', p_idempotency_key
    )
    RETURNING * INTO v_inserted;
  EXCEPTION
    WHEN exclusion_violation THEN
      GET STACKED DIAGNOSTICS v_message = MESSAGE_TEXT;
      IF v_message LIKE 'Vehicle reservation%' THEN
        RETURN jsonb_build_object('ok', false, 'error', 'vehicle_reserved');
      END IF;
      RETURN jsonb_build_object('ok', false, 'error', 'driver_reserved');
    WHEN unique_violation THEN
      SELECT * INTO v_existing
      FROM public.fleet_assignment_reservations
      WHERE agency_id = v_agency_id
        AND idempotency_key = p_idempotency_key;

      IF FOUND THEN
        IF v_existing.agency_job_id = p_agency_job_id
           AND v_existing.job_offer_id = p_job_offer_id
           AND v_existing.vehicle_id = p_vehicle_id
           AND v_existing.driver_employment_id = p_driver_employment_id
           AND v_existing.window_start = p_window_start
           AND v_existing.window_end = p_window_end THEN
          RETURN jsonb_build_object(
            'ok', true,
            'state', 'idempotent_replay',
            'reservation', to_jsonb(v_existing),
            'version', v_existing.version
          );
        END IF;
        RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_reused');
      END IF;

      RETURN jsonb_build_object('ok', false, 'error', 'agency_job_already_assigned');
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'state', 'created',
    'reservation', to_jsonb(v_inserted),
    'version', v_inserted.version
  );
END;
$$;

-- release_fleet_assignment (from 20261010000000_fleet_assignment_reservations.sql; authority -> dispatcher)
CREATE OR REPLACE FUNCTION public.release_fleet_assignment(
  p_reservation_id uuid,
  p_expected_version integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_current public.fleet_assignment_reservations%ROWTYPE;
  v_updated public.fleet_assignment_reservations%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['dispatcher']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT * INTO v_current
  FROM public.fleet_assignment_reservations
  WHERE id = p_reservation_id
    AND agency_id = v_agency_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reservation not found or access denied.';
  END IF;

  -- Exactly-once replay: an already released row, checked with the version the
  -- caller got back from its release, returns without a second write.
  IF v_current.status = 'released' AND v_current.version = p_expected_version THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state', 'already_released',
      'reservation', to_jsonb(v_current),
      'version', v_current.version
    );
  END IF;

  IF v_current.version <> p_expected_version THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'version_conflict',
      'current_version', v_current.version
    );
  END IF;

  IF v_current.status <> 'active' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'reservation_not_active',
      'current_version', v_current.version
    );
  END IF;

  UPDATE public.fleet_assignment_reservations
  SET status = 'released',
      released_reason = 'manual_release'
  WHERE id = p_reservation_id
    AND version = p_expected_version
  RETURNING * INTO v_updated;

  RETURN jsonb_build_object(
    'ok', true,
    'state', 'released',
    'reservation', to_jsonb(v_updated),
    'version', v_updated.version
  );
END;
$$;

-- agency_client_agreement_create (from 20261011000000_agency_members_clients_tariffs.sql; authority -> finance)
CREATE OR REPLACE FUNCTION public.agency_client_agreement_create(
  p_client_name text,
  p_client_gstin text DEFAULT NULL,
  p_payment_terms_days integer DEFAULT NULL,
  p_idempotency_key text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_name text := btrim(coalesce(p_client_name, ''));
  v_gstin text := nullif(upper(btrim(coalesce(p_client_gstin, ''))), '');
  v_existing public.agency_client_agreements%ROWTYPE;
  v_inserted public.agency_client_agreements%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['finance']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  IF v_key = '' THEN
    RAISE EXCEPTION 'Idempotency key is required.';
  END IF;

  IF v_name = '' THEN
    RAISE EXCEPTION 'Client name is required.';
  END IF;

  IF v_gstin IS NOT NULL AND v_gstin !~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$' THEN
    RAISE EXCEPTION 'GSTIN format is invalid.';
  END IF;

  IF p_payment_terms_days IS NOT NULL AND (p_payment_terms_days < 0 OR p_payment_terms_days > 365) THEN
    RAISE EXCEPTION 'Payment terms must be between 0 and 365 days.';
  END IF;

  SELECT * INTO v_existing
  FROM public.agency_client_agreements
  WHERE agency_id = v_agency_id AND idempotency_key = v_key;

  IF FOUND THEN
    IF v_existing.client_name = v_name THEN
      RETURN jsonb_build_object('ok', true, 'state', 'idempotent_replay', 'agreement', to_jsonb(v_existing));
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_reused');
  END IF;

  INSERT INTO public.agency_client_agreements (
    agency_id, client_name, client_gstin, payment_terms_days, status, idempotency_key, created_by
  ) VALUES (
    v_agency_id, v_name, v_gstin, p_payment_terms_days, 'active', v_key, auth.uid()
  )
  RETURNING * INTO v_inserted;

  RETURN jsonb_build_object('ok', true, 'state', 'created', 'agreement', to_jsonb(v_inserted));
END;
$$;

-- agency_client_agreement_update (from 20261011000000_agency_members_clients_tariffs.sql; authority -> finance)
CREATE OR REPLACE FUNCTION public.agency_client_agreement_update(
  p_agreement_id uuid,
  p_expected_version integer,
  p_patch jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_current public.agency_client_agreements%ROWTYPE;
  v_updated public.agency_client_agreements%ROWTYPE;
  v_name text;
  v_gstin text;
  v_terms integer;
  v_status text;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['finance']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT * INTO v_current
  FROM public.agency_client_agreements
  WHERE id = p_agreement_id AND agency_id = v_agency_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Client agreement not found or access denied.';
  END IF;

  IF v_current.version <> p_expected_version THEN
    RETURN jsonb_build_object('ok', false, 'error', 'version_conflict', 'current_version', v_current.version);
  END IF;

  v_name := v_current.client_name;
  v_gstin := v_current.client_gstin;
  v_terms := v_current.payment_terms_days;
  v_status := v_current.status;

  IF p_patch ? 'client_name' THEN
    v_name := btrim(coalesce(p_patch->>'client_name', ''));
    IF v_name = '' THEN
      RAISE EXCEPTION 'Client name is required.';
    END IF;
  END IF;

  IF p_patch ? 'client_gstin' THEN
    v_gstin := nullif(upper(btrim(coalesce(p_patch->>'client_gstin', ''))), '');
    IF v_gstin IS NOT NULL AND v_gstin !~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$' THEN
      RAISE EXCEPTION 'GSTIN format is invalid.';
    END IF;
  END IF;

  IF p_patch ? 'payment_terms_days' THEN
    v_terms := nullif(p_patch->>'payment_terms_days', '')::integer;
    IF v_terms IS NOT NULL AND (v_terms < 0 OR v_terms > 365) THEN
      RAISE EXCEPTION 'Payment terms must be between 0 and 365 days.';
    END IF;
  END IF;

  IF p_patch ? 'status' THEN
    v_status := p_patch->>'status';
    IF v_status IS NULL OR v_status NOT IN ('active', 'ended') THEN
      RAISE EXCEPTION 'Unknown agreement status.';
    END IF;
  END IF;

  UPDATE public.agency_client_agreements
  SET client_name = v_name,
      client_gstin = v_gstin,
      payment_terms_days = v_terms,
      status = v_status,
      version = version + 1
  WHERE id = p_agreement_id AND agency_id = v_agency_id
  RETURNING * INTO v_updated;

  RETURN jsonb_build_object('ok', true, 'state', 'updated', 'agreement', to_jsonb(v_updated));
END;
$$;

-- agency_client_site_create (from 20261011000000_agency_members_clients_tariffs.sql; authority -> finance)
CREATE OR REPLACE FUNCTION public.agency_client_site_create(
  p_agreement_id uuid,
  p_site_kind text,
  p_label text,
  p_address_line text,
  p_city text,
  p_state text,
  p_pincode text,
  p_idempotency_key text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_agreement public.agency_client_agreements%ROWTYPE;
  v_existing public.agency_client_sites%ROWTYPE;
  v_inserted public.agency_client_sites%ROWTYPE;
  v_pincode text := btrim(coalesce(p_pincode, ''));
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['finance']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  IF v_key = '' THEN
    RAISE EXCEPTION 'Idempotency key is required.';
  END IF;

  SELECT * INTO v_agreement
  FROM public.agency_client_agreements
  WHERE id = p_agreement_id AND agency_id = v_agency_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Client agreement not found or access denied.';
  END IF;

  IF p_site_kind IS NULL OR p_site_kind NOT IN ('bill_to', 'ship_to') THEN
    RAISE EXCEPTION 'Unknown site kind.';
  END IF;

  IF btrim(coalesce(p_label, '')) = '' OR btrim(coalesce(p_address_line, '')) = ''
     OR btrim(coalesce(p_city, '')) = '' OR btrim(coalesce(p_state, '')) = '' THEN
    RAISE EXCEPTION 'Site label, address, city and state are required.';
  END IF;

  IF v_pincode !~ '^[0-9]{6}$' THEN
    RAISE EXCEPTION 'Pincode must be six digits.';
  END IF;

  SELECT * INTO v_existing
  FROM public.agency_client_sites
  WHERE agency_id = v_agency_id AND idempotency_key = v_key;

  IF FOUND THEN
    IF v_existing.agreement_id = p_agreement_id
       AND v_existing.site_kind = p_site_kind
       AND v_existing.label = btrim(p_label) THEN
      RETURN jsonb_build_object('ok', true, 'state', 'idempotent_replay', 'site', to_jsonb(v_existing));
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_reused');
  END IF;

  IF v_agreement.status <> 'active' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'agreement_not_active');
  END IF;

  IF p_site_kind = 'bill_to' AND EXISTS (
    SELECT 1 FROM public.agency_client_sites s
    WHERE s.agreement_id = p_agreement_id AND s.site_kind = 'bill_to' AND s.status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'active_bill_to_exists');
  END IF;

  INSERT INTO public.agency_client_sites (
    agency_id, agreement_id, site_kind, label, address_line, city, state, pincode, status, idempotency_key
  ) VALUES (
    v_agency_id, p_agreement_id, p_site_kind, btrim(p_label), btrim(p_address_line),
    btrim(p_city), btrim(p_state), v_pincode, 'active', v_key
  )
  RETURNING * INTO v_inserted;

  RETURN jsonb_build_object('ok', true, 'state', 'created', 'site', to_jsonb(v_inserted));
END;
$$;

-- agency_client_site_update (from 20261011000000_agency_members_clients_tariffs.sql; authority -> finance)
CREATE OR REPLACE FUNCTION public.agency_client_site_update(
  p_site_id uuid,
  p_expected_version integer,
  p_patch jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_current public.agency_client_sites%ROWTYPE;
  v_updated public.agency_client_sites%ROWTYPE;
  v_label text;
  v_address text;
  v_city text;
  v_state text;
  v_pincode text;
  v_status text;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['finance']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  SELECT * INTO v_current
  FROM public.agency_client_sites
  WHERE id = p_site_id AND agency_id = v_agency_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Client site not found or access denied.';
  END IF;

  IF v_current.version <> p_expected_version THEN
    RETURN jsonb_build_object('ok', false, 'error', 'version_conflict', 'current_version', v_current.version);
  END IF;

  v_label := v_current.label;
  v_address := v_current.address_line;
  v_city := v_current.city;
  v_state := v_current.state;
  v_pincode := v_current.pincode;
  v_status := v_current.status;

  IF p_patch ? 'label' THEN
    v_label := btrim(coalesce(p_patch->>'label', ''));
    IF v_label = '' THEN RAISE EXCEPTION 'Site label, address, city and state are required.'; END IF;
  END IF;
  IF p_patch ? 'address_line' THEN
    v_address := btrim(coalesce(p_patch->>'address_line', ''));
    IF v_address = '' THEN RAISE EXCEPTION 'Site label, address, city and state are required.'; END IF;
  END IF;
  IF p_patch ? 'city' THEN
    v_city := btrim(coalesce(p_patch->>'city', ''));
    IF v_city = '' THEN RAISE EXCEPTION 'Site label, address, city and state are required.'; END IF;
  END IF;
  IF p_patch ? 'state' THEN
    v_state := btrim(coalesce(p_patch->>'state', ''));
    IF v_state = '' THEN RAISE EXCEPTION 'Site label, address, city and state are required.'; END IF;
  END IF;
  IF p_patch ? 'pincode' THEN
    v_pincode := btrim(coalesce(p_patch->>'pincode', ''));
    IF v_pincode !~ '^[0-9]{6}$' THEN RAISE EXCEPTION 'Pincode must be six digits.'; END IF;
  END IF;
  IF p_patch ? 'status' THEN
    v_status := p_patch->>'status';
    IF v_status IS NULL OR v_status NOT IN ('active', 'inactive') THEN
      RAISE EXCEPTION 'Unknown site status.';
    END IF;
  END IF;

  IF v_status = 'active' AND v_current.site_kind = 'bill_to' AND EXISTS (
    SELECT 1 FROM public.agency_client_sites s
    WHERE s.agreement_id = v_current.agreement_id
      AND s.site_kind = 'bill_to'
      AND s.status = 'active'
      AND s.id <> p_site_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'active_bill_to_exists');
  END IF;

  UPDATE public.agency_client_sites
  SET label = v_label,
      address_line = v_address,
      city = v_city,
      state = v_state,
      pincode = v_pincode,
      status = v_status,
      version = version + 1
  WHERE id = p_site_id AND agency_id = v_agency_id
  RETURNING * INTO v_updated;

  RETURN jsonb_build_object('ok', true, 'state', 'updated', 'site', to_jsonb(v_updated));
END;
$$;

-- agency_client_contact_create (from 20261011000000_agency_members_clients_tariffs.sql; authority -> finance)
CREATE OR REPLACE FUNCTION public.agency_client_contact_create(
  p_agreement_id uuid,
  p_full_name text,
  p_phone text,
  p_email text DEFAULT NULL,
  p_site_id uuid DEFAULT NULL,
  p_idempotency_key text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_agency_id uuid;
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_name text := btrim(coalesce(p_full_name, ''));
  v_phone text := regexp_replace(btrim(coalesce(p_phone, '')), '[[:space:]]', '', 'g');
  v_email text := nullif(lower(btrim(coalesce(p_email, ''))), '');
  v_agreement public.agency_client_agreements%ROWTYPE;
  v_existing public.agency_client_contacts%ROWTYPE;
  v_inserted public.agency_client_contacts%ROWTYPE;
BEGIN
  v_agency_id := public.resolve_caller_agency_for_scopes(ARRAY['finance']::text[]);

  IF NOT public.agency_is_operational(v_agency_id) THEN
    RAISE EXCEPTION 'Agency approval is required.';
  END IF;

  IF v_key = '' THEN
    RAISE EXCEPTION 'Idempotency key is required.';
  END IF;

  SELECT * INTO v_agreement
  FROM public.agency_client_agreements
  WHERE id = p_agreement_id AND agency_id = v_agency_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Client agreement not found or access denied.';
  END IF;

  IF v_name = '' THEN
    RAISE EXCEPTION 'Contact name is required.';
  END IF;

  IF v_phone !~ '^\+?[0-9]{10,15}$' THEN
    RAISE EXCEPTION 'Contact phone is invalid.';
  END IF;

  IF v_email IS NOT NULL AND v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'Contact email is invalid.';
  END IF;

  IF p_site_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.agency_client_sites s
    WHERE s.id = p_site_id AND s.agreement_id = p_agreement_id AND s.agency_id = v_agency_id
  ) THEN
    RAISE EXCEPTION 'Site not found for this agreement.';
  END IF;

  SELECT * INTO v_existing
  FROM public.agency_client_contacts
  WHERE agency_id = v_agency_id AND idempotency_key = v_key;

  IF FOUND THEN
    IF v_existing.agreement_id = p_agreement_id AND v_existing.full_name = v_name THEN
      RETURN jsonb_build_object('ok', true, 'state', 'idempotent_replay', 'contact', to_jsonb(v_existing));
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_reused');
  END IF;

  IF v_agreement.status <> 'active' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'agreement_not_active');
  END IF;

  INSERT INTO public.agency_client_contacts (
    agency_id, agreement_id, site_id, full_name, phone, email, status, idempotency_key
  ) VALUES (
    v_agency_id, p_agreement_id, p_site_id, v_name, v_phone, v_email, 'active', v_key
  )
  RETURNING * INTO v_inserted;

  RETURN jsonb_build_object('ok', true, 'state', 'created', 'contact', to_jsonb(v_inserted));
END;
$$;

